SUA.conversion:
const coverage = ctx.run.salary_coverage;
const amount = Number(
	get(ctx.subject.employment.terms, 'allowances.' + ctx.lookup.allowance + '.amount', 0)
);
const month_days = calendar_distance_days(month_start(coverage.from), month_end(coverage.to)) + 1;
return ((amount * ctx.calendar_days) / month_days) * ctx.paid_share;

OVERTIME.eligibility:
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'employee_extension_data', {});
if (get(facts, 'overtime_by_contract', false) === true) return true;
const category = get(terms, 'statutory_work_category', '');
if (['DOMESTIC', 'VESSEL_CREW'].includes(category)) return false;
if (ctx.month_wage <= ctx.lookup.monthly_wage_threshold) return true;
return ctx.lookup.manual_categories.includes(category);

OVERTIME.conversion:
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'employee_extension_data', {});
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * 8
			: 8
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', 8)
		)
	: normal;
const tier = Math.max(0, full - normal);
const orpHour = ctx.hour_rate;
const days = get(ctx, 'work.days', []);
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const ordinary = days
	.filter((day) => ['WORK', 'OFF'].includes(get(day, 'day_type', 'WORK')) && !holiday(day))
	.toSorted((a, b) => {
		const left = String(get(a, 'date', ''));
		const right = String(get(b, 'date', ''));
		if (left < right) return -1;
		return left > right ? 1 : 0;
	});
const band = (premium) => round(premium * orpHour, ctx.lookup.minor_unit, 'HALF_UP');
const hoursOf = (day) =>
	Math.max(0, Number(get(day, get(day, 'day_type', 'WORK') === 'OFF' ? 'worked_hours' : 'overtime_hours', 0)));
if (partTime)
	return sum(
		ordinary.map((day) => {
			const hours = hoursOf(day);
			return (
				Math.min(hours, tier) * band(ctx.lookup.part_time_premium) +
				Math.max(0, hours - tier) * band(ctx.lookup.standard_premium)
			);
		})
	);
const months = ordinary
	.map((day) => String(get(day, 'date', '')).slice(0, 7))
	.filter((month, index, all) => all.indexOf(month) === index);
return sum(
	months.map((month) =>
		round(
			sum(ordinary.filter((day) => String(get(day, 'date', '')).slice(0, 7) === month).map(hoursOf)) *
				band(ctx.lookup.standard_premium),
			ctx.lookup.minor_unit,
			'HALF_UP'
		)
	)
);

lookup.entitlement:
const employment = ctx.subject.employment;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? ctx.lookup.part_time_service_bands : ctx.lookup.service_bands;
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from'));
const months = calendar_completed_months(started, ctx.as_of);
const [opening] = bands;
const exit = get(employment, 'effective_range.to', null);
const exitMonths = exit === null ? null : calendar_completed_months(started, exit);
const accruedTo = exit !== null && exitMonths < opening.service_months ? exit : ctx.as_of;
if (months < opening.service_months) return Math.round((opening.days * calendar_completed_months(started, add_days(accruedTo, 1))) / opening.service_months);
const band = bands.filter((b) => b.service_months <= months).at(-1);
if (exit === null) return band.days;
const years = Math.floor(months / 12);
if (exitMonths < years * 12 || exitMonths >= (years + 1) * 12) return band.days;
const served = calendar_completed_months(add_months(started, years * 12), add_days(exit, 1));
return Math.round((band.days * served) / 12);

ANNUAL_LEAVE.payout:
const days = Number(get(ctx.entry, 'quantity', 0));
const daily = round(ctx.month_wage / 26, ctx.lookup.minor_unit, 'HALF_UP');
return daily * days;

lookup.entitlement:
const employment = ctx.subject.employment;
if (ctx.lookup.eligibility.excluded_employment_types.includes(get(employment, 'terms.statutory_work_category', ''))) return 0;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? ctx.lookup.part_time_service_bands : ctx.lookup.service_bands;
const months = calendar_completed_months(get(employment, 'service_started_on', get(employment, 'effective_range.from')), ctx.as_of);
return get(bands.filter((band) => band.service_months <= months).at(-1), 'days', 0);

BONUS.eligibility:
const exit = get(ctx.subject.employment, 'effective_range.to', null);
if (!(ctx.entry.quantity > 0)) return false;
if (exit === null) return true;
return ctx.entry.incurred_on <= exit;

